<?php
declare(strict_types=1);require_once __DIR__.'/includes/layout.php';require_once __DIR__.'/includes/service_engine.php';require_once __DIR__.'/includes/helpers.php';login_required();$pdo=db();$serviceId=(string)($_GET['id']??$_POST['service_id']??'');$s=$pdo->prepare('SELECT * FROM `laundry` WHERE `laundry_id`=?');$s->execute([$serviceId]);$service=$s->fetch();if(!$service)redirect('laundry.php');$customers=active_customers();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$cid=post_int('customer_id');$date=post('service_date',date('Y-m-d'));$price=(float)($_POST['service_price']??0);$extraVal=post_int('service_extra');if($cid&&$date){try{$pdo->prepare('INSERT INTO `laundry_service`(customer_id,`laundry_id`,employee_id,`laundry_date`,`laundry_amount`,`laundry_price`) VALUES(?,?,?,?,?,?)')->execute([$cid,$serviceId,(int)user()['employee_id'],$date,$extraVal,$price]);service_total($date,$cid);flash('success','Laundry service added.');}catch(Throwable $e){flash('error',$e->getMessage());}}redirect('laundry_service.php?id='.urlencode($serviceId));}
$q=$pdo->prepare("SELECT x.*,CONCAT(c.customer_firstname,' ',c.customer_lastname) customer FROM `laundry_service` x JOIN customer c ON c.customer_id=x.customer_id WHERE x.`laundry_id`=? ORDER BY x.`laundry_date` DESC");$q->execute([$serviceId]);$rows=$q->fetchAll();page_header('Laundry Service','laundry');?>
<div class="page-head"><div><h1>Add Laundry Service</h1><p class="muted"><?=e($service['laundry_details']??'')?></p></div><a class="btn" href="laundry.php">Back</a></div>
<section class="card"><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="service_id" value="<?=e($serviceId)?>"><label>Customer<select name="customer_id" required><option value="">Select active customer</option><?php foreach($customers as $c):?><option value="<?=$c['customer_id']?>"><?=e($c['customer_firstname'].' '.$c['customer_lastname'])?></option><?php endforeach;?></select></label><label>Date<input type="date" name="service_date" value="<?=date('Y-m-d')?>" required></label><label>Price<input type="number" min="0" step="0.01" name="service_price" value="0"></label><label>Laundry Amount<input name="service_extra"></label><div class="full"><button class="btn primary">Add Service</button></div></form></section>
<section class="card table-wrap"><h2>Service History</h2><table><thead><tr><th>Customer</th><th>Date</th><th>Laundry Amount</th><th>Price</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['customer'])?></td><td><?=e($r['laundry_date'])?></td><td><?=e($r['laundry_amount'])?></td><td><?=money($r['laundry_price'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4" class="empty">No service records.</td></tr><?php endif;?></tbody></table></section>
<?php page_footer();?>
